    @Override
    public int hashCode() {
        String str = "";
        str += curProduct.hashCode();
        str += amtdGroup.hashCode();
        str += xlPage1Ln.hashCode();
        str += totPage1Ln.hashCode();
        str += savProduct.hashCode();
        str += cirrusX360Record.hashCode();
        str += work.hashCode();
       return str.hashCode();
    }

