    @Override
    public int hashCode() {
        String str = "";
        str += savKey.hashCode();
        str += headingLine1Group.hashCode();
        str += hdPage1Ln4a.hashCode();
        str += reportRecord.hashCode();
        str += hdPage1Ln3.hashCode();
        str += hdPage1Ln6b.hashCode();
        str += ms10frptMbrDetailRec.hashCode();
        str += hdPage1Ln6.hashCode();
        str += work.hashCode();
        str += xlPage1Ln.hashCode();
        str += hdPage1Ln6c.hashCode();
        str += waWorkOfDate.hashCode();
        str += hdPage1Ln5.hashCode();
        str += monthNameTable.hashCode();
        str += dtPage3Ln10.hashCode();
        str += hdPage1Ln6a.hashCode();
        str += hdPage1Ln4.hashCode();
        str += hdPage1Ln2.hashCode();
        str += surDate.hashCode();
       return str.hashCode();
    }

